func TestCalculateFare(t *testing.T) {
	tests := []struct {
		name string
		eta  time.Duration
		want float64
	}{
		{"zero uses minimum", 0, 3.50},
		{"negative uses minimum", -5 * time.Minute, 3.50},
		{"below minimum", 2 * time.Minute, 3.50},
		{"exactly minimum threshold", 140 * time.Second, 3.50},
		{"just above minimum", 3 * time.Minute, 4.50},
		{"whole minutes", 10 * time.Minute, 15.00},
		{"fractional minutes", 4*time.Minute + 30*time.Second, 6.75},
		{"rounded to cents", 7*time.Minute + 7*time.Second, 10.68},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := CalculateFare(tt.eta); got != tt.want {
				t.Errorf("CalculateFare(%v) = %v, want %v", tt.eta, got, tt.want)
			}
		})
	}
}

