package location

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/go-sql-driver/mysql"
)

// errRideNotFound is returned when a ride history entry does not exist.
var errRideNotFound = errors.New("ride history entry not found")

const rideHistoryColumns = "id, pickup_name, dropoff_name, request_time, driver_plate, fare"

func (d *database) createRideHistoryTable() error {
	_, err := d.db.Exec(rideHistorySchema)
	return err
}

// retryRideHistory reports whether err is a "table doesn't exist" error on
// ride_history, creating the table if so. Unlike shouldRetry it does not go
// through setupDB, which also (re)seeds the locations table.
func (d *database) retryRideHistory(err error) bool {
	var mysqlErr *mysql.MySQLError
	if errors.As(err, &mysqlErr) && mysqlErr.Number == 1146 {
		return d.createRideHistoryTable() == nil
	}
	return false
}

func scanRideHistory(row interface{ Scan(...any) error }) (RideHistoryEntry, error) {
	var (
		e    RideHistoryEntry
		fare sql.NullFloat64
	)
	if err := row.Scan(&e.ID, &e.PickupName, &e.DropoffName, &e.RequestTime, &e.DriverPlate, &fare); err != nil {
		return RideHistoryEntry{}, err
	}
	if fare.Valid {
		e.Fare = &fare.Float64
	}
	return e, nil
}

// ListRideHistory returns the most recent rides (newest first, at most limit)
// together with the total number of rides.
func (d *database) ListRideHistory(ctx context.Context, limit int) (*RideHistory, error) {
	history, err := d.listRideHistory(ctx, limit)
	if err != nil && d.retryRideHistory(err) {
		history, err = d.listRideHistory(ctx, limit)
	}
	return history, err
}

func (d *database) listRideHistory(ctx context.Context, limit int) (*RideHistory, error) {
	history := &RideHistory{Rides: []RideHistoryEntry{}}
	if err := d.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM ride_history").Scan(&history.Total); err != nil {
		return nil, err
	}

	rows, err := d.db.QueryContext(ctx,
		"SELECT "+rideHistoryColumns+" FROM ride_history ORDER BY request_time DESC, id DESC LIMIT ?", limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		e, err := scanRideHistory(rows)
		if err != nil {
			return nil, err
		}
		history.Rides = append(history.Rides, e)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return history, nil
}

// GetRideHistory returns a single ride, or errRideNotFound.
func (d *database) GetRideHistory(ctx context.Context, id int64) (*RideHistoryEntry, error) {
	get := func() (RideHistoryEntry, error) {
		return scanRideHistory(d.db.QueryRowContext(ctx,
			"SELECT "+rideHistoryColumns+" FROM ride_history WHERE id = ?", id))
	}
	e, err := get()
	if err != nil && d.retryRideHistory(err) {
		e, err = get()
	}
	if errors.Is(err, sql.ErrNoRows) {
		return nil, errRideNotFound
	}
	if err != nil {
		return nil, err
	}
	return &e, nil
}

