const (
	defaultRideHistoryLimit = 50
	maxRideHistoryLimit     = 500
	maxRideHistoryBodyBytes = 1 << 16
)

// writeJSON marshals v and writes it as the response body.
func (s *Server) writeJSON(w http.ResponseWriter, r *http.Request, v any) {
	data, err := json.Marshal(v)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(r.Context()).Error("cannot marshal response", zap.Error(err))
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

// writeRideHistoryError maps database errors to HTTP status codes.
func (s *Server) writeRideHistoryError(w http.ResponseWriter, r *http.Request, err error) {
	status := http.StatusInternalServerError
	if errors.Is(err, errRideNotFound) {
		status = http.StatusNotFound
	}
	httperr.HandleError(w, err, status)
	s.logger.For(r.Context()).Error("ride history request failed", zap.Error(err))
}

func (s *Server) listRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	limit := defaultRideHistoryLimit
	if limitStr := r.URL.Query().Get("limit"); limitStr != "" {
		var err error
		limit, err = strconv.Atoi(limitStr)
		if err != nil || limit < 1 || limit > maxRideHistoryLimit {
			httperr.HandleError(w, fmt.Errorf("parameter 'limit' must be an integer between 1 and %d",
				maxRideHistoryLimit), http.StatusBadRequest)
			return
		}
	}

	history, err := s.database.ListRideHistory(ctx, limit)
	if err != nil {
		s.writeRideHistoryError(w, r, err)
		return
	}
	s.writeJSON(w, r, history)
}

func (s *Server) createRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	var req struct {
		PickupName  string     `json:"pickupName"`
		DropoffName string     `json:"dropoffName"`
		RequestTime *time.Time `json:"requestTime"`
	}
	err := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxRideHistoryBodyBytes)).Decode(&req)
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}
	if req.PickupName == "" || req.DropoffName == "" {
		httperr.HandleError(w, errors.New("'pickupName' and 'dropoffName' are required"), http.StatusBadRequest)
		return
	}
	requestTime := time.Now()
	if req.RequestTime != nil {
		requestTime = *req.RequestTime
	}

	entry, err := s.database.CreateRideHistory(ctx, req.PickupName, req.DropoffName, requestTime)
	if err != nil {
		s.writeRideHistoryError(w, r, err)
		return
	}
	s.writeJSON(w, r, entry)
}

func (s *Server) updateRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		httperr.HandleError(w, errors.New("missing required 'id' parameter"), http.StatusBadRequest)
		return
	}
	id, err := strconv.ParseInt(idStr, 10, 64)
	if err != nil || id < 1 {
		httperr.HandleError(w, errors.New("parameter 'id' is not a positive integer"), http.StatusBadRequest)
		return
	}

	var req struct {
		DriverPlate string   `json:"driverPlate"`
		Fare        *float64 `json:"fare"`
	}
	err = json.NewDecoder(http.MaxBytesReader(w, r.Body, maxRideHistoryBodyBytes)).Decode(&req)
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}
	// fare is a decimal(10,2) column
	if req.DriverPlate == "" || req.Fare == nil || *req.Fare < 0 || *req.Fare >= 1e8 {
		httperr.HandleError(w, errors.New("'driverPlate' and a 'fare' between 0 and 99999999.99 are required"),
			http.StatusBadRequest)
		return
	}

	entry, err := s.database.UpdateRideHistory(ctx, id, req.DriverPlate, *req.Fare)
	if err != nil {
		s.writeRideHistoryError(w, r, err)
		return
	}
	s.writeJSON(w, r, entry)
}
