package frontend

import (
	"net/http"
	"net/http/httputil"
	"net/url"

	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/httperr"
	"github.com/signadot/hotrod/pkg/log"
)

// locationRideHistoryPath is the ride history endpoint of the location service.
const locationRideHistoryPath = "/ride-history"

// newRideHistoryProxy returns a handler that forwards ride history requests
// (method, query, body and status code are passed through unchanged) to the
// location service at addr. The outgoing request goes through an
// instrumented transport so trace context and baggage, which carry the
// sandbox routing key, are propagated to the location service.
func newRideHistoryProxy(tracerProvider trace.TracerProvider, logger log.Factory, addr string) http.Handler {
	target := &url.URL{Scheme: "http", Host: addr}
	return &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(target)
			pr.Out.URL.Path = locationRideHistoryPath
			pr.Out.URL.RawPath = ""
		},
		Transport: otelhttp.NewTransport(http.DefaultTransport, otelhttp.WithTracerProvider(tracerProvider)),
		ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
			logger.For(r.Context()).Error("ride history request to location service failed", zap.Error(err))
			httperr.HandleError(w, err, http.StatusBadGateway)
		},
	}
}
