// Driver notification body, e.g. "Driver T712345C arriving in 3m20s. Fare: $5.00"
const DRIVER_PLATE_REGEX = /Driver\s+(.*?)\s+arriving/;
const FARE_REGEX = /Fare:\s*\$(\d+(?:\.\d+)?)/;

export const parseDriverPlate = (body: string): string | undefined => {
    const match = body.match(DRIVER_PLATE_REGEX);
    return match ? match[1] : undefined;
}

export const parseFare = (body: string): number | undefined => {
    const match = body.match(FARE_REGEX);
    return match ? parseFloat(match[1]) : undefined;
}

