import {useCallback, useEffect, useRef, useState} from "react";
import {apiGet, apiPatch, apiPost} from "../services/http.ts";
import {RideHistory, RideHistoryEntry} from "../types/rideHistory.ts";

export const useRideHistory = () => {
    const [history, setHistory] = useState<RideHistory>({rides: [], total: 0});
    const [error, setError] = useState(false);

    // Ride history entry IDs by request ID. The entry is created right after
    // dispatching, which can race with the driver notification, so the promise
    // is stored and awaited before updating the entry.
    const entriesRef = useRef(new Map<number, Promise<number | undefined>>());

    const refresh = useCallback(async () => {
        try {
            // nonse avoids cached responses, same as the notifications polling
            setHistory(await apiGet<RideHistory>(`/ride-history?nonse=${Math.random()}`));
            setError(false);
        } catch (e) {
            setError(true);
        }
    }, []);

    useEffect(() => {
        refresh();
    }, [refresh]);

    const createEntry = useCallback((requestID: number, pickupName: string, dropoffName: string,
                                     headers: Record<string, string>) => {
        const created = apiPost<RideHistoryEntry>('/ride-history', {
            pickupName,
            dropoffName,
            requestTime: new Date().toISOString(),
        }, headers)
            .then(entry => {
                refresh();
                return entry.id;
            })
            .catch(() => undefined);
        entriesRef.current.set(requestID, created);
        return created;
    }, [refresh]);

    const updateEntry = useCallback(async (requestID: number, driverPlate: string, fare: number,
                                           headers: Record<string, string>) => {
        const id = await entriesRef.current.get(requestID);
        if (id === undefined) return;

        try {
            await apiPatch<RideHistoryEntry>(`/ride-history?id=${id}`, {driverPlate, fare}, headers);
        } finally {
            refresh();
        }
    }, [refresh]);

    return {
        history,
        historyError: error,
        createEntry,
        updateEntry,
    };
};
EOF
